contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _amount, uint _unlockTime, uint _am) public payable {
        require(_amount > 0, "need nonzero amount");
        require(address(this).balance >= _amount, "not enough ether");

        // record before values
        uint beforeSelf = address(this).balance;
        uint beforeContract = address(c).balance;
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // Put: payable call, fills Acc[this]
        c.Put{value: _amount}(_unlockTime);

        // read after values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContract = address(c).balance;

        // Collect attempt
        bool collectedReverted;
        try c.Collect(_am) {
            collectedReverted = false;
        } catch {
            collectedReverted = true;
        }

        (uint finalUnlock, uint finalBal) = c.Acc(address(this));
        uint finalSelf = address(this).balance;
        uint finalContract = address(c).balance;

        // General rule:
        // 1) Put added exactly _amount to the account balance.
        // 2) Put credited unlockTime >= block.timestamp.
        // 3) Contract's balance grew by _amount on Put.
        // 4) If Collect reverted, no value moved (finalSelf == afterSelf); if successful,
        //    account balance decreased by _am and the contract sent exactly _am.
        assert(
            afterBal == beforeBal + _amount &&
            afterUnlock >= block.timestamp &&
            afterContract == beforeContract + _amount &&
            (
                collectedReverted
                    ? (finalBal == afterBal && finalContract == afterContract && finalSelf == afterSelf)
                    : (finalBal == afterBal - _am && finalContract == afterContract - _am && finalSelf == afterSelf + _am)
            )
        );
    }

    receive() external payable {}
}

